const $=id=>document.getElementById(id);let revision=0;
async function api(action,body){const response=await fetch('/api/compute?action='+action,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.detail||data.error||'Connection unavailable.');return data;}
function show(connection){revision=connection?.revision||0;$('endpoint').value=connection?.endpoint||'';$('stored').textContent=connection?.credentialConfigured?'A credential is stored (hidden).':'No runtime credential is stored.';$('credential').value='';$('operation').value='keep';$('credential').disabled=true;}
$('operation').addEventListener('change',()=>{$('credential').disabled=$('operation').value!=='replace';if($('credential').disabled)$('credential').value='';});
$('connection').addEventListener('submit',async event=>{event.preventDefault();const credential={operation:$('operation').value};if(credential.operation==='replace')credential.value=$('credential').value;try{const result=await api('connection',{revision,endpoint:$('endpoint').value,credential});show(result.connection);$('status').textContent='Connection saved. Test it to confirm availability.';}catch(error){$('status').textContent=error.message;}finally{$('credential').value='';}});
$('test').addEventListener('click',async()=>{$('test').disabled=true;$('status').textContent='Checking the saved runtime…';try{await api('test',{});$('status').textContent='Connected: an approved source is available.';}catch(error){$('status').textContent=error.message;}finally{$('test').disabled=false;}});
try{show((await api('connection')).connection);$('status').textContent='Ready to configure.';}catch(error){$('status').textContent=error.message;for(const control of $('connection').elements)control.disabled=true;}
